// <work-message> — one turn of a conversation. Ported from
// desktop/src/lib/chat/AssistantMessageView.svelte (+ the role bubble chrome).
//
// The body is the message's living source (markdown / org-with-components).
// It renders SANITIZED markdown (bold/italic/lists/headings/code/links — see
// ./markdown.js, HTML-escaped first) and weaves inline `#+begin_src component`
// blocks into <work-gen-block> cards in document order. The agent edits this
// source; the rendered turn is the view of it (preview ≡ source).
//
// Usage:
//   <work-message role="user">What changed in the deploy?</work-message>
//   <work-message role="assistant">**Done.** Here is the diff…</work-message>
//
// `role` styles the turn (user | assistant | system | tool). The body can be
// passed as light-DOM textContent or via the `text` attribute/property.
import { WbElement, html, css, define } from "../../core/element.js";
import { unsafeHTML } from "lit/directives/unsafe-html.js";
import { defineVariants, variantAttrs } from "../../core/variants.js";
import { renderMarkdown, splitComponents } from "./markdown.js";
import "./wb-gen-block.js";

const VARIANTS = defineVariants({
  role: { options: ["user", "assistant", "system", "tool"], default: "assistant" },
});

export class WbMessage extends WbElement {
  static variants = VARIANTS;
  static props = [...variantAttrs(VARIANTS), "text", "name"];

  static styles = css`
    :host { display: block; font-family: var(--work-font); color: var(--work-fg); }
    .turn { display: flex; flex-direction: column; gap: var(--work-space-1); }
    .meta { display: flex; align-items: center; gap: var(--work-space-2);
      font: 600 11px var(--work-font-mono); letter-spacing: .08em; text-transform: uppercase;
      color: var(--work-fg-subtle); }
    .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--work-fg-subtle); }
    .body {
      font-size: var(--work-text); line-height: 1.55;
      display: flex; flex-direction: column; gap: var(--work-space-3);
    }

    /* user turn: a brand-tinted bubble, right-shouldered */
    :host([role="user"]) .turn { align-items: flex-end; }
    :host([role="user"]) .body {
      background: var(--work-brand-soft); color: var(--work-fg);
      border: 1px solid color-mix(in srgb, var(--work-brand) 24%, transparent);
      border-radius: var(--work-radius-lg);
      padding: var(--work-space-3) var(--work-space-4);
      max-width: 80%;
    }
    :host([role="user"]) .dot { background: var(--work-brand); }

    /* assistant turn: flat on the surface */
    :host([role="assistant"]) .body { max-width: 100%; }

    /* system / tool: muted monospace card */
    :host([role="system"]) .body,
    :host([role="tool"]) .body {
      font-family: var(--work-font-mono); font-size: var(--work-text-sm);
      color: var(--work-fg-muted); background: var(--work-surface-soft);
      border: 1px solid var(--work-border); border-radius: var(--work-radius-sm);
      padding: var(--work-space-2) var(--work-space-3);
    }

    /* rendered markdown rhythm */
    .md > *:first-child { margin-top: 0; }
    .md > *:last-child { margin-bottom: 0; }
    .md p { margin: 0 0 .5em; }
    .md strong { font-weight: 650; }
    .md em { font-style: italic; }
    .md h1, .md h2, .md h3 { margin: .6em 0 .35em; line-height: 1.3; font-weight: 650; }
    .md h1 { font-size: 1.18em; } .md h2 { font-size: 1.1em; } .md h3 { font-size: 1.02em; }
    .md ul, .md ol { margin: .25em 0 .5em; padding-left: 1.35em; }
    .md li { margin: .15em 0; }
    .md li::marker { color: var(--work-fg-muted); }
    .md code { font-family: var(--work-font-mono); font-size: .88em;
      background: var(--work-surface-soft); border: 1px solid var(--work-border);
      border-radius: var(--work-radius-4px); padding: .05em .3em; }
    .md pre { margin: .4em 0 .55em; padding: .6em .75em; background: var(--work-surface-soft);
      border: 1px solid var(--work-border); border-radius: var(--work-radius-7px); overflow-x: auto; }
    .md pre code { background: none; border: 0; padding: 0; font-size: .85em; }
    .md a { color: var(--work-brand); text-decoration: underline; text-underline-offset: 2px; }
  `;

  /** Source: explicit `text` prop/attr, else light-DOM textContent. */
  get source() {
    if (this._text != null) return this._text;
    if (this.hasAttribute("text")) return this.getAttribute("text");
    return (this._initialText ?? "").trim();
  }
  set text(v) {
    this._text = v;
    if (this._connected) this.requestUpdate();
  }

  connectedCallback() {
    // Capture light-DOM text once for the textContent path (shadow render
    // leaves light DOM intact).
    if (this._initialText == null) this._initialText = this.textContent || "";
    this._connected = true;
    super.connectedCallback();
  }

  render() {
    const role = this.attr("role", "assistant");
    const name = this.attr("name") || role;
    const segments = splitComponents(this.source);

    return html`<div class="turn">
      <div class="meta"><span class="dot"></span><span>${name}</span></div>
      <div class="body">${segments.map((seg) =>
        seg.kind === "prose"
          ? html`<div class="md">${unsafeHTML(renderMarkdown(seg.source))}</div>`
          : this._genBlock(seg),
      )}</div>
    </div>`;
  }

  /** Render a component segment as a <work-gen-block> with structured props. */
  _genBlock(seg) {
    const el = document.createElement("work-gen-block");
    el.setAttribute("type", seg.type);
    for (const [k, v] of Object.entries(seg.props)) el.setAttribute(k, v);
    el.textContent = seg.body;
    return el;
  }
}

define("work-message", WbMessage);

// WbElement — the base for every <wb-*> element, re-based onto Lit.
//
// Lit is the FLOOR's engine now (the approved adoption pass): surgical template
// updates instead of an innerHTML nuke, while every workponents convention is
// preserved so the rest of the library migrates mechanically. Lit is loaded as a
// bare specifier ("lit") — buildless via an import map in the demos, a peer dep
// for SDK consumers (see README / demo/lit-foundation.html). No bundler, no
// `bun install`.
//
// Conventions (unchanged — the whole library follows these):
//   • Shadow DOM (open) for style isolation; --work-* tokens inherit through it.
//   • `static styles` = the component CSS as a Lit `css``` CSSResult (was a
//     string). Use ONLY var(--work-*). Variants targeted via :host([name="value"]).
//   • `render()` returns a Lit `html``` TemplateResult (was a string) — surgical
//     updates, no innerHTML rewrite.
//   • `static props` = reflected attributes that re-render on change (variants,
//     state). They are mapped to Lit reactive properties automatically.
//   • `static variants` defaults are reflected on connect (before first paint) so
//     :host([name="value"]) selectors always match.
//   • Capability is reached through `this.host` (the Dock seam), never hardcoded.
//   • Register with `define()` (idempotent — safe to load twice).
//
// `attr()` / `boolAttr()` helpers are preserved for elements that read attributes
// directly in render(). Re-exports `html` + `css` so domain files import the whole
// authoring surface from one place:
//   import { WbElement, html, css, define } from "../core/element.js";

import { LitElement, html, css } from "lit";
import { getHost } from "./host.js";

export { html, css };

export class WbElement extends LitElement {
  /** @type {import("lit").CSSResult} component CSS — override with css``; use only var(--work-*) */
  static styles = css``;

  /** @type {string[]} reflected attributes that trigger a re-render */
  static props = [];

  // Register each subclass's `static props` as Lit reactive properties so an
  // attribute change fires attributeChangedCallback + re-renders (the old
  // observedAttributes contract). NOTE: a base-class `static get properties()` is
  // NOT honored — Lit's finalize() only reads each class's OWN `properties`. So we
  // hook finalize() and createProperty() per subclass instead. Reflect ONLY the
  // short variant enums (so el.variant = "soft" still matches :host([variant]));
  // never reflect data attributes like `rows`/`csv`/`query` (can be huge strings).
  static finalize() {
    super.finalize();
    const variants = this.variants || {};
    for (const name of this.props || []) {
      const key = this._propKey(name);
      // Skip names that already exist on the prototype as a method/getter (e.g. a
      // `variant(name)` helper, an `open()` method). Creating a reactive accessor
      // there THROWS in Lit dev mode ("declared as a reactive property but it's
      // actually declared as a value on the prototype"). The attribute is still
      // OBSERVED via observedAttributes below, so attribute changes still fire
      // attributeChangedCallback → the element's reload/requestUpdate runs.
      if (key in this.prototype) continue;
      this.createProperty(key, {
        type: String,
        attribute: name,
        reflect: Object.prototype.hasOwnProperty.call(variants, name),
      });
    }
  }

  // Guarantee every `static props` attribute is OBSERVED (the browser reads this
  // at customElements.define() time). This is the bulletproof half: even if Lit's
  // reactive-property finalize timing misses one, attribute changes still fire
  // attributeChangedCallback → the element's reload/requestUpdate handler runs.
  static get observedAttributes() {
    const base = super.observedAttributes || [];
    return Array.from(new Set([...base, ...(this.props || [])]));
  }

  // Attribute names may contain dashes; reactive-property keys must be identifiers.
  static _propKey(name) {
    return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  }

  /** The Dock/Host capability seam — local | runtime (RCP) | kernel. */
  get host() {
    return getHost();
  }

  /** Read an attribute with a default. */
  attr(name, fallback = null) {
    return this.hasAttribute(name) ? this.getAttribute(name) : fallback;
  }

  /** Read a boolean attribute (present = true). */
  boolAttr(name) {
    return this.hasAttribute(name);
  }

  /** Override: return the template (Lit `html```). */
  render() {
    return html`<slot></slot>`;
  }

  connectedCallback() {
    // Reflect default variants BEFORE Lit's first render so :host([name="value"])
    // selectors match the very first paint, even when the author sets only some
    // (e.g. tone without variant).
    const v = this.constructor.variants;
    if (v) {
      for (const [name, def] of Object.entries(v)) {
        if (!this.hasAttribute(name)) this.setAttribute(name, def.default);
      }
    }
    super.connectedCallback();
  }
}

/** Idempotent custom-element registration (safe across double-loads). */
export function define(name, ctor) {
  if (!customElements.get(name)) customElements.define(name, ctor);
  return ctor;
}

// The Host/Dock seam — one capability surface for every element.
//
// A workponent never hardcodes where a capability runs. It asks the Host, which
// resolves `local` (in-WASM / browser-native), `runtime` (a Workbooks runtime
// over RCP), or `kernel` (oql.wasm) per the platform-model — so the SAME element
// (e.g. <wb-table>) runs in-WASM locally or on the runtime tier for huge data,
// no code fork. Capability elements declare what they need; the Host provisions
// it (the same grant model toolkits use) and reports availability so the element
// degrades cleanly when a capability is absent (e.g. voice without a key).
//
// Phase 0: a minimal, portable seam (no Tauri/Svelte). When a runtime URL is
// configured it routes over fetch/WebSocket (mirroring desktop/src/lib/rcp);
// otherwise it serves local capabilities and reports the rest unavailable.

let _host = null;

export class WbHost {
  /** @param {{ runtimeUrl?: string|null, tenant?: string }} [opts] */
  constructor(opts = {}) {
    this.runtimeUrl = opts.runtimeUrl || null;
    this.tenant = opts.tenant || "local";
    this._caps = new Set(["local"]); // in-WASM/browser caps are always present
  }

  /** Is a capability reachable here? (elements gate UI on this) */
  available(cap) {
    return this._caps.has(cap) || (this.runtimeUrl != null && cap !== "voice");
  }

  /** Unary capability call — routed to the runtime when present. */
  async request(path, { method = "POST", body } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const res = await fetch(this.runtimeUrl.replace(/\/$/, "") + path, {
      method,
      headers: { "content-type": "application/json", "x-tenant": this.tenant },
      body: body != null ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) throw new Error(`wb-host ${res.status} ${path}`);
    return res.json();
  }

  /** Streaming capability — a WebSocket to the runtime. */
  socket(path, { onMessage } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const url = this.runtimeUrl.replace(/^http/, "ws").replace(/\/$/, "") + path;
    const ws = new WebSocket(url);
    if (onMessage) ws.addEventListener("message", (e) => onMessage(e.data));
    return ws;
  }
}

/** Configure the shared Host (call once at app/workbook boot). */
export function configureHost(opts) {
  _host = new WbHost(opts);
  return _host;
}

/** The shared Host singleton (a local-only Host by default). */
export function getHost() {
  if (!_host) {
    // Honor a global hint (a workbook/desktop can set window.__WB_RUNTIME_URL__).
    const url = typeof window !== "undefined" ? window.__WB_RUNTIME_URL__ : null;
    _host = new WbHost({ runtimeUrl: url || null });
  }
  return _host;
}

// Variants — the cva-style contract for web components.
//
// Variants are REFLECTED ATTRIBUTES the component CSS targets via :host([...]).
// This util doesn't generate classes; it (1) declares the allowed values +
// defaults for an element (so authoring is typed/validated and the design-lint
// can check conformance), and (2) normalizes the live attribute, applying the
// default when unset or invalid. The actual styling lives in the component CSS:
//
//   static styles = `
//     :host([variant="solid"]) button { background: var(--work-brand); }
//     :host([size="sm"])      button { padding: var(--work-space-1) var(--work-space-2); }
//   `;
//
// Usage in an element:
//   static variants = defineVariants({
//     variant: { options: ["solid", "soft", "ghost"], default: "solid" },
//     size:    { options: ["sm", "md", "lg"],        default: "md" },
//     tone:    { options: ["brand", "neutral", "ok", "warn", "err"], default: "brand" },
//   });
//   // in render(): this.variant("variant") -> the resolved value

export function defineVariants(spec) {
  return spec;
}

/** Resolve a variant attribute on `el` to a valid value (default on miss). */
export function resolveVariant(el, spec, name) {
  const def = spec[name];
  if (!def) return el.getAttribute(name);
  const v = el.getAttribute(name);
  return def.options.includes(v) ? v : def.default;
}

/** Every variant attribute name an element declares (for observedAttributes). */
export function variantAttrs(spec) {
  return Object.keys(spec || {});
}

/** Design-lint helper: report any variant attr set to a non-allowed value. */
export function lintVariants(el, spec) {
  const bad = [];
  for (const [name, def] of Object.entries(spec || {})) {
    const v = el.getAttribute(name);
    if (v != null && !def.options.includes(v)) bad.push({ name, value: v, allowed: def.options });
  }
  return bad;
}

// Tiny, dependency-free Markdown → sanitized HTML. Ported from
// desktop/src/lib/chat/markdown.ts (the Waldo plain-text assistant path).
//
// SECURITY: the source is HTML-escaped FIRST, so no raw LLM markup ever
// reaches the DOM. The only HTML emitted is the small fixed tag set this
// module generates itself (p, strong, em, code, pre, ul/ol/li, h1-h3, a, br).
// Links are restricted to http(s)/mailto (+ relative) and carry rel=noopener.

/** Escape the five HTML-significant characters. Run on ALL LLM/user text
 *  before any markup is woven in. */
export function esc(s) {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/** Only allow safe link schemes. Anything else renders as plain text. */
function safeHref(url) {
  const u = url.trim();
  if (/^(https?:\/\/|mailto:)/i.test(u)) return u;
  if (/^\/\//.test(u) || /^\/[^/]/.test(u)) return u;
  return null;
}

/** Inline spans: code, bold, italic, links. Operates on ALREADY-escaped
 *  text so the markup characters matched are literal, never HTML. Inline
 *  code is extracted first so emphasis inside it stays literal. */
function inline(escaped) {
  const codes = [];
  let s = escaped.replace(/`([^`]+)`/g, (_m, c) => {
    codes.push(`<code>${c}</code>`);
    return `�${codes.length - 1}�`;
  });

  // Links [text](url) — url is already escaped; validate the raw scheme.
  s = s.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (m, text, rawUrl) => {
    const href = safeHref(rawUrl.replace(/&amp;/g, "&"));
    if (!href) return m;
    return `<a href="${esc(href)}" target="_blank" rel="noopener noreferrer">${text}</a>`;
  });

  s = s.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
  s = s.replace(/__([^_]+)__/g, "<strong>$1</strong>");
  s = s.replace(/(^|[^*])\*([^*\n]+)\*/g, "$1<em>$2</em>");
  s = s.replace(/(^|[^_])_([^_\n]+)_/g, "$1<em>$2</em>");

  // Restore code spans.
  s = s.replace(/�(\d+)�/g, (_m, i) => codes[Number(i)]);
  return s;
}

/** Render Markdown to sanitized HTML. */
export function renderMarkdown(src) {
  const raw = String(src ?? "").replace(/\r\n?/g, "\n");
  const lines = raw.split("\n");
  const blocks = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    // Fenced code block ``` … ```
    if (/^\s*```/.test(line)) {
      const code = [];
      i++;
      while (i < lines.length && !/^\s*```/.test(lines[i])) {
        code.push(lines[i]);
        i++;
      }
      i++; // skip closing fence
      blocks.push({ t: "pre", code: code.join("\n") });
      continue;
    }

    // Blank line — block separator.
    if (/^\s*$/.test(line)) {
      i++;
      continue;
    }

    // Heading # .. ###
    const h = line.match(/^\s*(#{1,3})\s+(.*)$/);
    if (h) {
      blocks.push({ t: "h", level: h[1].length, text: h[2].trim() });
      i++;
      continue;
    }

    // Lists — gather consecutive items of one type.
    const ulm = line.match(/^\s*[-*+]\s+(.*)$/);
    const olm = line.match(/^\s*\d+[.)]\s+(.*)$/);
    if (ulm || olm) {
      const ordered = !!olm;
      const items = [];
      while (i < lines.length) {
        const m = ordered
          ? lines[i].match(/^\s*\d+[.)]\s+(.*)$/)
          : lines[i].match(/^\s*[-*+]\s+(.*)$/);
        if (!m) break;
        items.push(m[1]);
        i++;
      }
      blocks.push({ t: ordered ? "ol" : "ul", items });
      continue;
    }

    // Paragraph — gather until blank / block start.
    const para = [];
    while (
      i < lines.length &&
      !/^\s*$/.test(lines[i]) &&
      !/^\s*```/.test(lines[i]) &&
      !/^\s*#{1,3}\s+/.test(lines[i]) &&
      !/^\s*[-*+]\s+/.test(lines[i]) &&
      !/^\s*\d+[.)]\s+/.test(lines[i])
    ) {
      para.push(lines[i]);
      i++;
    }
    blocks.push({ t: "p", lines: para });
  }

  return blocks
    .map((b) => {
      switch (b.t) {
        case "h":
          return `<h${b.level}>${inline(esc(b.text))}</h${b.level}>`;
        case "pre":
          return `<pre><code>${esc(b.code)}</code></pre>`;
        case "ul":
        case "ol":
          return `<${b.t}>${b.items.map((it) => `<li>${inline(esc(it))}</li>`).join("")}</${b.t}>`;
        case "p":
          return `<p>${b.lines.map((l) => inline(esc(l))).join("<br>")}</p>`;
        default:
          return "";
      }
    })
    .join("");
}

// ─── conversation-as-source ─────────────────────────────────────────────
// The reinvention: the agent edits a living markdown/org artifact; the thread
// is that document. Inline component blocks are authored as
// `#+begin_src component :type <t> …` … `#+end_src` (Babel-style header args),
// rendered as themed cards — NOT a JSON IR. Ported from messageRender.ts.

const BLOCK_RE =
  /^[ \t]*#\+begin_src[ \t]+component\b([^\n]*)\n([\s\S]*?)^[ \t]*#\+end_src[ \t]*$/gim;

/** Parse Babel-style header args (`:type callout :tone warn`). The first
 *  `:type` value is pulled out; the rest become props. */
function parseHeaderArgs(header) {
  const props = {};
  const re = /:([a-zA-Z][\w-]*)[ \t]+([^:\n][^\n]*?)(?=[ \t]+:[a-zA-Z]|$)/g;
  for (const m of header.matchAll(re)) props[m[1].toLowerCase()] = m[2].trim();
  const type = props.type ?? "";
  delete props.type;
  return { type, props };
}

/** Split a message body into ordered prose + inline component segments.
 *  Prose segments → markdown; component segments → <work-gen-block>. */
export function splitComponents(text) {
  const src = String(text ?? "");
  const segments = [];
  let last = 0;
  for (const m of src.matchAll(BLOCK_RE)) {
    const start = m.index ?? 0;
    if (start > last) {
      const prose = src.slice(last, start);
      if (prose.trim()) segments.push({ kind: "prose", source: prose });
    }
    const { type, props } = parseHeaderArgs(m[1]);
    segments.push({
      kind: "component",
      type: type || "callout",
      props,
      body: m[2].replace(/\n+$/, ""),
    });
    last = start + m[0].length;
  }
  if (last < src.length) {
    const prose = src.slice(last);
    if (prose.trim()) segments.push({ kind: "prose", source: prose });
  }
  if (segments.length === 0 && src.trim()) {
    segments.push({ kind: "prose", source: src });
  }
  return segments;
}

/** Parse a `kv`/`share` component body: one `key: value` per line. */
export function parseKvBody(body) {
  return String(body ?? "")
    .split("\n")
    .map((l) => l.trim())
    .filter(Boolean)
    .map((l) => {
      const i = l.indexOf(":");
      return i === -1
        ? [l, ""]
        : [l.slice(0, i).trim(), l.slice(i + 1).trim()];
    });
}

// <work-gen-block> — an inline component block the agent emits inside a turn.
// Ported from desktop/src/lib/chat/ChatComponent.svelte. The agent authors
// these as `#+begin_src component :type <t> …` blocks in the living document;
// they render as themed cards reading STRUCTURED props/body — never raw LLM
// HTML. This is the "generated UI in the document" surface: NOT a JSON IR,
// the block IS the source.
//
// Types: callout (info/warn/ok/error banner) · kv (key/value table) ·
//        button (action; fires work-intent) · link (themed external link) ·
//        share (member chips + invite button; fires work-intent).
// Unknown types fall back to a labeled code block so nothing vanishes.
//
// Usage (props as attributes; body via textContent):
//   <work-gen-block type="callout" tone="warn" title="Heads up">…body…</work-gen-block>
//
// Interactive blocks emit a `work-intent` CustomEvent (bubbles, composed) the
// thread / host can observe — they never execute LLM-authored code.
import { WbElement, html, css, define } from "../../core/element.js";
import { svg as litSvg } from "lit";
import { parseKvBody } from "./markdown.js";

const ICONS = {
  info: "M12 17v-5m0-4h.01M12 22a10 10 0 100-20 10 10 0 000 20z",
  warn: "M12 9v4m0 4h.01M10.3 3.9 1.8 18a2 2 0 001.7 3h17a2 2 0 001.7-3L14.7 3.9a2 2 0 00-3.4 0z",
  ok: "M22 11.1V12a10 10 0 11-5.9-9.1M22 4 12 14.01l-3-3",
  err: "M12 22a10 10 0 100-20 10 10 0 000 20zM15 9l-6 6m0-6 6 6",
  send: "M22 2 11 13M22 2l-7 20-4-9-9-4 20-7z",
  out: "M18 13v6a2 2 0 01-2 2H5a2 2 0 01-2-2V8a2 2 0 012-2h6M15 3h6v6M10 14 21 3",
  users: "M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2M9 11a4 4 0 100-8 4 4 0 000 8m14 10v-2a4 4 0 00-3-3.87M16 3.13A4 4 0 0116 11",
};

function icon(d, cls = "icon") {
  return litSvg`<svg class=${cls} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d=${d}></path></svg>`;
}

export class WbGenBlock extends WbElement {
  static props = ["type", "tone", "title", "label", "href", "action", "target", "done"];

  static styles = css`
    :host { display: block; font-family: var(--work-font); color: var(--work-fg); }
    .card {
      border-radius: var(--work-radius);
      font-size: var(--work-text);
      line-height: 1.5;
      max-width: 720px;
    }
    .icon { width: 15px; height: 15px; flex: none; }

    /* callout */
    .callout { display: flex; gap: var(--work-space-2); padding: var(--work-space-3) var(--work-space-4);
      border: 1px solid var(--work-border); background: var(--work-surface); }
    .callout .icon { margin-top: 2px; color: var(--work-fg-muted); }
    .ctitle { font-weight: 600; margin-bottom: 2px; }
    .ctext { white-space: pre-wrap; word-break: break-word; }
    :host([tone="warn"]) .callout { border-color: color-mix(in srgb, var(--work-warn) 40%, transparent); background: color-mix(in srgb, var(--work-warn) 7%, var(--work-surface)); }
    :host([tone="warn"]) .callout .icon { color: var(--work-warn); }
    :host([tone="ok"]) .callout   { border-color: color-mix(in srgb, var(--work-ok) 40%, transparent); background: color-mix(in srgb, var(--work-ok) 7%, var(--work-surface)); }
    :host([tone="ok"]) .callout .icon { color: var(--work-ok); }
    :host([tone="error"]) .callout,
    :host([tone="err"]) .callout  { border-color: color-mix(in srgb, var(--work-err) 40%, transparent); background: color-mix(in srgb, var(--work-err) 7%, var(--work-surface)); }
    :host([tone="error"]) .callout .icon,
    :host([tone="err"]) .callout .icon { color: var(--work-err); }

    /* kv table */
    .kv { border: 1px solid var(--work-border); background: var(--work-surface); overflow: hidden; }
    .kvtitle { padding: var(--work-space-2) var(--work-space-3); font-weight: 600;
      border-bottom: 1px solid var(--work-border); background: var(--work-surface-soft); }
    table { width: 100%; border-collapse: collapse; }
    th, td { text-align: left; padding: var(--work-space-2) var(--work-space-3);
      border-bottom: 1px solid var(--work-border); vertical-align: top; }
    tr:last-child th, tr:last-child td { border-bottom: 0; }
    th { width: 38%; color: var(--work-fg-muted); font-weight: 500;
      font-family: var(--work-font-mono); font-size: var(--work-text-sm); }

    /* button / link / share — interactive */
    .btn {
      display: inline-flex; align-items: center; gap: var(--work-space-2);
      padding: var(--work-space-2) var(--work-space-4);
      border: 0; border-radius: var(--work-radius-sm);
      background: var(--work-brand); color: var(--work-on-brand);
      font: 600 var(--work-text) var(--work-font); cursor: pointer;
      transition: filter var(--work-dur) var(--work-ease), background var(--work-dur) var(--work-ease);
    }
    .btn:hover { filter: brightness(1.06); }
    .btn:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--work-ring); }
    .btn[data-done] { background: var(--work-brand-soft); color: var(--work-fg); cursor: default; }
    .btn .icon { width: 14px; height: 14px; }

    .link {
      display: inline-flex; align-items: center; gap: var(--work-space-2);
      padding: var(--work-space-2) var(--work-space-3);
      border: 1px solid var(--work-border); border-radius: var(--work-radius-sm);
      background: var(--work-surface); color: var(--work-brand);
      font: 500 var(--work-text) var(--work-font); text-decoration: none; width: fit-content;
    }
    .link:hover { border-color: var(--work-border-strong); }
    .link .icon { width: 13px; height: 13px; }

    .share { display: flex; flex-direction: column; gap: var(--work-space-3);
      padding: var(--work-space-3) var(--work-space-4);
      border: 1px solid var(--work-border); border-radius: var(--work-radius); background: var(--work-surface); }
    .shead { display: inline-flex; align-items: center; gap: var(--work-space-2); font-weight: 600; }
    .shead .icon { color: var(--work-fg-muted); }
    .starget { font-size: var(--work-text-sm); color: var(--work-fg-muted); }
    .members { display: flex; align-items: center; gap: var(--work-space-1); flex-wrap: wrap; }
    .member { display: inline-grid; place-items: center; width: 26px; height: 26px;
      border-radius: 50%; background: var(--work-brand-soft); color: var(--work-fg);
      font-size: var(--work-text-2xs); font-weight: 700; border: 1px solid var(--work-border); }
    .mcount { margin-left: var(--work-space-1); font-size: var(--work-text-sm); color: var(--work-fg-muted); }

    /* unknown fallback */
    .unknown { border: 1px dashed var(--work-border-strong); background: var(--work-surface-soft);
      padding: var(--work-space-3) var(--work-space-3); }
    .ulabel { font-size: var(--work-text-label); text-transform: uppercase; letter-spacing: .06em;
      color: var(--work-fg-subtle); margin-bottom: var(--work-space-1); }
    pre { margin: 0; white-space: pre-wrap; font-family: var(--work-font-mono); font-size: var(--work-text-sm); }
  `;

  /** The raw block body (light-DOM textContent). */
  get body() {
    return (this.textContent || "").trim();
  }

  /** Fire a sideband intent the thread/host observes; mark done. */
  _fire(action, detail = {}) {
    this.setAttribute("done", "");
    this.dispatchEvent(
      new CustomEvent("work-intent", {
        bubbles: true,
        composed: true,
        detail: { action, ...detail },
      }),
    );
  }

  _onButton() {
    const target = parseKvBody(this.body).find(([k]) => k === "target")?.[1] || this.attr("target", "");
    this._fire(this.attr("action", "button"), { label: this.attr("label", this.body), target });
  }

  _onShare() {
    const f = Object.fromEntries(parseKvBody(this.body));
    const members = (f.members || "").split(",").map((m) => m.trim()).filter(Boolean);
    this._fire("share", { target: f.target, members, role: f.role });
  }

  render() {
    const type = this.attr("type", "callout");
    const tone = this.attr("tone", "info");
    const title = this.attr("title");
    const body = this.body;
    const done = this.boolAttr("done");

    if (type === "kv") {
      const rows = parseKvBody(body);
      return html`<div class="card kv">${title ? html`<div class="kvtitle">${title}</div>` : ""}<table><tbody>${rows.map(
        ([k, v]) => html`<tr><th>${k}</th><td>${v}</td></tr>`,
      )}</tbody></table></div>`;
    }

    if (type === "button") {
      const label = done ? this.attr("doneLabel", "Done") : this.attr("label", body || "Run");
      return html`<button class="card btn" ?data-done=${done} @click=${this._onButton}>${icon(done ? ICONS.ok : ICONS.send)}<span>${label}</span></button>`;
    }

    if (type === "link") {
      const href = this.attr("href", "#");
      const safe = /^(https?:\/\/|mailto:|\/)/i.test(href) ? href : "#";
      return html`<a class="card link" href=${safe} target="_blank" rel="noopener noreferrer">${icon(ICONS.out)}<span>${this.attr("label", body || href)}</span></a>`;
    }

    if (type === "share") {
      const f = Object.fromEntries(parseKvBody(body));
      const members = (f.members || "").split(",").map((m) => m.trim()).filter(Boolean);
      return html`<div class="card share">
        <div class="shead">${icon(ICONS.users)}<span>${title || "Share with your org"}</span></div>
        ${f.target ? html`<div class="starget">${f.target}</div>` : ""}
        ${members.length ? html`<div class="members">${members.map(
          (m) => html`<span class="member" title=${m}>${m.split(" ").map((w) => w[0]).join("").slice(0, 2).toUpperCase()}</span>`,
        )}<span class="mcount">${members.length} people · ${f.role || "Editor"}</span></div>` : ""}
        <button class="btn" ?data-done=${done} @click=${this._onShare}>${icon(done ? ICONS.ok : ICONS.send)}<span>${done ? "Invited" : "Send invite"}</span></button>
      </div>`;
    }

    if (type === "callout") {
      const ic = tone === "warn" ? ICONS.warn : tone === "ok" ? ICONS.ok : (tone === "error" || tone === "err") ? ICONS.err : ICONS.info;
      return html`<div class="card callout"><span class="icon">${icon(ic, "")}</span><div>${title ? html`<div class="ctitle">${title}</div>` : ""}<div class="ctext">${body}</div></div></div>`;
    }

    return html`<div class="card unknown"><div class="ulabel">component: ${type}</div><pre>${body}</pre></div>`;
  }
}

define("work-gen-block", WbGenBlock);
